import{_ as e,o as a,c as r,a5 as s}from"./chunks/framework.CslsFoWx.js";const h=JSON.parse('{"title":"Marchés et réglementation","description":"","frontmatter":{},"headers":[],"relativePath":"commercial/marches.md","filePath":"commercial/marches.md","lastUpdated":1793427717000}'),n={name:"commercial/marches.md"};function o(d,t,i,c,l,u){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="marches-et-reglementation" tabindex="-1">Marchés et réglementation <a class="header-anchor" href="#marches-et-reglementation" aria-label="Permalink to &quot;Marchés et réglementation&quot;">​</a></h1><h2 id="tunisie" tabindex="-1">Tunisie <a class="header-anchor" href="#tunisie" aria-label="Permalink to &quot;Tunisie&quot;">​</a></h2><h3 id="obligation-nacef" tabindex="-1">Obligation NACEF <a class="header-anchor" href="#obligation-nacef" aria-label="Permalink to &quot;Obligation NACEF&quot;">​</a></h3><p>La caisse enregistreuse homologuée devient obligatoire pour <strong>tout établissement de consommation sur place</strong>, par vagues :</p><table tabindex="0"><thead><tr><th>Date</th><th>Assujettis</th></tr></thead><tbody><tr><td>01/11/2025</td><td>Restaurants touristiques classés, salons de thé, cafés 2e/3e catégorie</td></tr><tr><td><strong>01/07/2026</strong></td><td>Autres <strong>personnes morales</strong></td></tr><tr><td>01/07/2027</td><td>Personnes physiques au régime réel</td></tr><tr><td>01/07/2028</td><td>Autres personnes physiques</td></tr></tbody></table><p>Base légale : art. 48 LF2016, décret 2019-1126, arrêté du 14/10/2025 (<a href="/VendoraSystem-docs/commercial/legal">textes</a>). Sanctions jusqu&#39;à 3 ans d&#39;emprisonnement et 50 000 DT d&#39;amende pour manipulation des données.</p><p><strong>Exigences connues</strong> (le cahier des charges n&#39;est accessible que depuis la Tunisie) : module de sécurisation fiscale homologué, <strong>QR code sur chaque ticket</strong>, mentions obligatoires, <strong>synchronisation quasi temps réel</strong> avec la plateforme du ministère, clôture journalière. Côté produit, la <a href="/VendoraSystem-docs/specs/15-fiscal-compliance">spec 15</a> prévoit ces règles (RG-FISC-30 → 38) comme <strong>provisoires</strong> ; le socle commun (scellement chaîné, clôtures, file de retransmission offline) est déjà livré.</p><h3 id="paiements" tabindex="-1">Paiements <a class="header-anchor" href="#paiements" aria-label="Permalink to &quot;Paiements&quot;">​</a></h3><p>Cash dominant, ardoise (« karna ») courante. Intégrations visées : <strong>Flouci</strong> (1,3 % HT, API QR sur partenariat), <strong>Konnect</strong> et <strong>Paymee</strong> (agrégateurs avec sandbox et webhooks), <strong>TUNPAY</strong> (QR unique national, norme non publiée). Le POS reste <strong>intégrateur</strong> : chaque marchand a son propre compte, le POS n&#39;encaisse jamais pour autrui (sinon statut d&#39;établissement de paiement).</p><h2 id="france" tabindex="-1">France <a class="header-anchor" href="#france" aria-label="Permalink to &quot;France&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Obligation</th><th>Ce que le produit fait</th><th>État</th></tr></thead><tbody><tr><td><strong>Art. 286 CGI</strong> — inaltérabilité, sécurisation, conservation, archivage</td><td>Ventes scellées et chaînées, corrections en +/-, mode formation « factice », clôtures J/M/A avec totaux perpétuels, archive annuelle en format ouvert avec notice, attestation éditeur</td><td><span class="badge ok">Fait</span> certification NF525 / LNE à engager</td></tr><tr><td><strong>E-reporting B2C</strong> via plateforme agréée (GE/ETI 2026, PME/micro 01/09/2027)</td><td>Agrégats journaliers par taux de TVA à produire et transmettre</td><td><span class="badge todo">À faire</span> phase 3</td></tr><tr><td><strong>Titres-restaurant</strong> (Conecs, paiement scindé, 25 €/jour)</td><td>Tender dédié, éligibilité par article</td><td><span class="badge todo">À faire</span> phase 3</td></tr><tr><td><strong>Pourboires</strong> (hors CA, hors TVA, par salarié)</td><td>Ligne pourboire distincte, rapport par bénéficiaire</td><td><span class="badge ok">Fait</span> lot 2.9</td></tr></tbody></table><h2 id="concurrence-en-un-coup-d-œil" tabindex="-1">Concurrence en un coup d&#39;œil <a class="header-anchor" href="#concurrence-en-un-coup-d-œil" aria-label="Permalink to &quot;Concurrence en un coup d&#39;œil&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Acteur</th><th>Marché</th><th>Prix d&#39;entrée</th><th>Offline</th><th>Multi-OS</th><th>Notre écart</th></tr></thead><tbody><tr><td>Kesti</td><td>TN</td><td>29 DT/mois</td><td>~ mono-poste</td><td>?</td><td>Multi-appareils, multi-vertical</td></tr><tr><td>Al-Makhzan</td><td>TN</td><td>79 TND/mois</td><td>~</td><td>?</td><td>KDS équivalent ; eux ont menu QR et food-cost (nos phases 3-4)</td></tr><tr><td>Wasel</td><td>TN</td><td>licence 199-599 DT</td><td>✓ local, Windows mono-poste</td><td>✗</td><td>Cloud, mobile, multi-magasins</td></tr><tr><td>Square / SumUp</td><td>FR</td><td>0 € + 1,65-1,75 %</td><td>~ limité</td><td>✓ / ~</td><td>Pas de commission, offline réel</td></tr><tr><td>L&#39;Addition</td><td>FR</td><td>49 €/mois</td><td>✓ routeur local</td><td>✗ Apple</td><td>Android + iOS, multi-vertical</td></tr><tr><td>Lightspeed</td><td>FR</td><td>89-249 €/mois</td><td>~</td><td>✗ iPad</td><td>Prix, multi-vertical</td></tr></tbody></table><p>Matrice complète et sources : <a href="/VendoraSystem-docs/commercial/etude-concurrentielle">étude concurrentielle</a>.</p>',14)])])}const p=e(n,[["render",o]]);export{h as __pageData,p as default};
